mapper.select:
SELECT s.schedule_id                          AS id,
       l.title                                AS title,
       DATE_FORMAT(s.sched_date, '%Y-%m-%d')  AS start,
       s.survey_id                            AS surveyId
  FROM survey_schedule s
  JOIN survey_list l ON l.survey_id = s.survey_id
 WHERE s.user_id = #{userId}
   AND s.sched_date >= #{start}
   AND s.sched_date <  #{end}
 ORDER BY s.sched_date, l.title

mapper.insert:
INSERT INTO survey_schedule (user_id, survey_id, sched_date)
SELECT #{userId}, l.survey_id, #{date}
  FROM survey_list l
 WHERE l.survey_id = #{surveyId}
   AND (l.user_id = #{userId}
         OR l.sgg_cd = #{guSgg})
